import type { LocalPhoto } from './photo-model';
import { readPreparedPhoto } from './photo-device';
import { prepareThumbnailWithIO, THUMBNAIL_MAX_BYTES, THUMBNAIL_QUALITY } from './thumbnail-model';

// Only files generated by this adapter can be removed through its public API.
const generatedFiles = new Set<string>();
export async function prepareThumbnail(photo: LocalPhoto, signal: AbortSignal): Promise<LocalPhoto> {
  if (signal.aborted) throw new Error('Thumbnail preparation cancelled.');
  await readPreparedPhoto(photo);
  if (signal.aborted) throw new Error('Thumbnail preparation cancelled.');
  const { File } = await import('expo-file-system');
  const { ImageManipulator, SaveFormat } = await import('expo-image-manipulator');
  return prepareThumbnailWithIO(photo, signal, {
    async render(uri, dimensions) {
      const context = ImageManipulator.manipulate(uri);
      let rendered: Awaited<ReturnType<typeof context.renderAsync>> | undefined;
      try {
        context.resize(dimensions);
        rendered = await context.renderAsync();
        const output = await rendered.saveAsync({ format: SaveFormat.JPEG, compress: THUMBNAIL_QUALITY, base64: false });
        if (output.uri !== uri) generatedFiles.add(output.uri);
        return output.uri;
      } finally {
        try { rendered?.release(); } catch { /* Attempt both native releases independently. */ }
        try { context.release(); } catch { /* Output validation and file cleanup remain independent. */ }
      }
    },
    async inspect(uri) {
      const file = new File(uri);
      if (!file.exists || !file.size || file.size > THUMBNAIL_MAX_BYTES) throw new Error('Generated thumbnail file is unavailable.');
      const bytes = new Uint8Array(await file.arrayBuffer());
      return { size: file.size, bytes };
    },
    remove(uri) {
      if (!generatedFiles.delete(uri)) return;
      try { const file = new File(uri); if (file.exists) file.delete(); } catch { /* Best effort generated cache cleanup. */ }
    },
  });
}
export function removeThumbnail(photo: LocalPhoto): void {
  if (!generatedFiles.delete(photo.uri)) return;
  void import('expo-file-system').then(({ File }) => {
    try { const file = new File(photo.uri); if (file.exists) file.delete(); } catch { /* Never remove the source photo. */ }
  }).catch(() => {});
}
